From f72f13861da21072e5e74c829ba1848afe07c464 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:20:30 +0100
Subject: [PATCH] applets/quicklaunch: open files dropped on an application
 launcher

Dropping a file on Quicklaunch always made room for a new launcher, and
on release nothing was added because the saved URL list was empty by the
time it was inserted. Open the files with the hovered app instead.

BUG: 475312
---
 applets/quicklaunch/IconItem.qml      |  2 +-
 applets/quicklaunch/Popup.qml         |  2 +-
 applets/quicklaunch/UrlModel.qml      |  1 +
 applets/quicklaunch/main.qml          | 16 +++++++++++++++-
 applets/quicklaunch/quicklaunch_p.cpp | 16 +++++++++++++++-
 applets/quicklaunch/quicklaunch_p.h   |  1 +
 6 files changed, 34 insertions(+), 4 deletions(-)

diff --git a/applets/quicklaunch/IconItem.qml b/applets/quicklaunch/IconItem.qml
index ab6d8aba3..d7f6034a5 100644
--- a/applets/quicklaunch/IconItem.qml
+++ b/applets/quicklaunch/IconItem.qml
@@ -241,7 +241,7 @@ Item {
                 anchors.fill: parent
                 imagePath: "widgets/viewitem"
                 prefix: "hover"
-                visible: iconItem.dragging || iconItem.url === "quicklaunch:drop"
+                visible: iconItem.dragging || iconItem.url === "quicklaunch:drop" || (!iconItem.isPopupItem && iconItem.launcherModel.dropTargetIndex === iconItem.index)
             }

             PlasmaCore.ToolTipArea {
diff --git a/applets/quicklaunch/Popup.qml b/applets/quicklaunch/Popup.qml
index 2224a29b8..4fa0b17ca 100644
--- a/applets/quicklaunch/Popup.qml
+++ b/applets/quicklaunch/Popup.qml
@@ -95,7 +95,7 @@ Item {
             } else if (event.mimeData.hasUrls) {
                 var index = listView.indexAt(event.x, event.y);
                 popupModel.clearDropMarker();
-                var urls = event.mimeData.urls;
+                var urls = Array.from(event.mimeData.urls, url => url.toString());
                 event.accept(event.proposedAction);
                 Qt.callLater(function() {
                     popupModel.insertUrls(index == -1 ? popupModel.count : index, urls);
diff --git a/applets/quicklaunch/UrlModel.qml b/applets/quicklaunch/UrlModel.qml
index 7de6b7c06..1e003a3e5 100644
--- a/applets/quicklaunch/UrlModel.qml
+++ b/applets/quicklaunch/UrlModel.qml
@@ -10,6 +10,7 @@ ListModel {
     id: listModel

     property int dropMarkerIndex : -1
+    property int dropTargetIndex : -1

     signal urlsChanged()

diff --git a/applets/quicklaunch/main.qml b/applets/quicklaunch/main.qml
index 012b52556..4cdc2e185 100644
--- a/applets/quicklaunch/main.qml
+++ b/applets/quicklaunch/main.qml
@@ -28,6 +28,7 @@ PlasmoidItem {
     property bool dragging : false
     property int internalDragIndex: -1
     property int internalDragOriginalIndex: -1
+    property bool dropOpensUrls: false

     Layout.minimumWidth: LayoutManager.minimumWidth()
     Layout.minimumHeight: LayoutManager.minimumHeight()
@@ -212,6 +213,7 @@ PlasmoidItem {
                     root.internalDragOriginalIndex = -1;

                     var urls = event.mimeData.urls;
+                    root.dropOpensUrls = !urls.some(url => url.toString().endsWith(".desktop"));
                     if (urls.length === 1) {
                         var dragUrl = urls[0].toString();
                         var modelUrls = launcherModel.urls();
@@ -236,7 +238,14 @@ PlasmoidItem {
                         launcherModel.move(root.internalDragIndex, index, 1);
                         root.internalDragIndex = index;
                     }
+                } else if (root.dropOpensUrls && index >= 0 && index !== launcherModel.dropMarkerIndex && (grid.itemAtIndex(index) as IconItem).launcher.isApplication) {
+                    if (launcherModel.dropMarkerIndex >= 0 && index > launcherModel.dropMarkerIndex) {
+                        index--;
+                    }
+                    launcherModel.clearDropMarker();
+                    launcherModel.dropTargetIndex = index;
                 } else {
+                    launcherModel.dropTargetIndex = -1;
                     launcherModel.showDropMarker(index);
                 }

@@ -253,6 +262,7 @@ PlasmoidItem {
                     root.internalDragOriginalIndex = -1;
                 } else {
                     launcherModel.clearDropMarker();
+                    launcherModel.dropTargetIndex = -1;
                 }
             }

@@ -264,10 +274,14 @@ PlasmoidItem {
                     root.internalDragOriginalIndex = -1;
                     event.accept(Qt.IgnoreAction);
                     root.saveConfiguration();
+                } else if (launcherModel.dropTargetIndex >= 0) {
+                    logic.openUrlsWith(launcherModel.get(launcherModel.dropTargetIndex).url, Array.from(event.mimeData.urls, url => url.toString()));
+                    launcherModel.dropTargetIndex = -1;
+                    event.accept(Qt.CopyAction);
                 } else {
                     var index = dropArea.gridIndexAt(event.x, event.y);
                     launcherModel.clearDropMarker();
-                    var urls = event.mimeData.urls;
+                    var urls = Array.from(event.mimeData.urls, url => url.toString());
                     event.accept(event.proposedAction);
                     Qt.callLater(function() {
                         launcherModel.insertUrls(index == -1 ? launcherModel.count : index, urls);
diff --git a/applets/quicklaunch/quicklaunch_p.cpp b/applets/quicklaunch/quicklaunch_p.cpp
index 68e666100..980a67bff 100644
--- a/applets/quicklaunch/quicklaunch_p.cpp
+++ b/applets/quicklaunch/quicklaunch_p.cpp
@@ -20,11 +20,13 @@
 #include <KConfigGroup>
 #include <KDesktopFile>
 #include <KFileItem>
+#include <KIO/ApplicationLauncherJob>
 #include <KIO/CommandLauncherJob>
 #include <KIO/OpenUrlJob>
 #include <KNotificationJobUiDelegate>
 #include <KOpenWithDialog>
 #include <KPropertiesDialog>
+#include <KService>

 #include <kio/global.h>

@@ -39,6 +41,7 @@ QVariantMap QuicklaunchPrivate::launcherData(const QUrl &url)
     QString icon;
     QString genericName;
     QVariantList jumpListActions;
+    bool isApplication = false;

     if (url.scheme() == QLatin1String("quicklaunch")) {
         // Ignore internal scheme
@@ -51,6 +54,7 @@ QVariantMap QuicklaunchPrivate::launcherData(const QUrl &url)
             name = f.readName();
             icon = f.readIcon();
             genericName = f.readGenericName();
+            isApplication = f.hasApplicationType();
             if (name.isEmpty()) {
                 name = QFileInfo(url.toLocalFile()).fileName();
             }
@@ -95,7 +99,8 @@ QVariantMap QuicklaunchPrivate::launcherData(const QUrl &url)
     return QVariantMap{{QStringLiteral("applicationName"), name},
                        {QStringLiteral("iconName"), icon},
                        {QStringLiteral("genericName"), genericName},
-                       {QStringLiteral("jumpListActions"), jumpListActions}};
+                       {QStringLiteral("jumpListActions"), jumpListActions},
+                       {QStringLiteral("isApplication"), isApplication}};
 }

 void QuicklaunchPrivate::openUrl(const QUrl &url)
@@ -106,6 +111,15 @@ void QuicklaunchPrivate::openUrl(const QUrl &url)
     job->start();
 }

+void QuicklaunchPrivate::openUrlsWith(const QUrl &launcherUrl, const QList<QUrl> &urls)
+{
+    const KService::Ptr service(new KService(launcherUrl.toLocalFile()));
+    auto *job = new KIO::ApplicationLauncherJob(service);
+    job->setUrls(urls);
+    job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+    job->start();
+}
+
 void QuicklaunchPrivate::openExec(const QString &exec)
 {
     KIO::CommandLauncherJob *job = new KIO::CommandLauncherJob(exec);
diff --git a/applets/quicklaunch/quicklaunch_p.h b/applets/quicklaunch/quicklaunch_p.h
index 0336d0adf..67602d335 100644
--- a/applets/quicklaunch/quicklaunch_p.h
+++ b/applets/quicklaunch/quicklaunch_p.h
@@ -22,6 +22,7 @@ public:

     Q_INVOKABLE QVariantMap launcherData(const QUrl &url);
     Q_INVOKABLE void openUrl(const QUrl &url);
+    Q_INVOKABLE void openUrlsWith(const QUrl &launcherUrl, const QList<QUrl> &urls);
     Q_INVOKABLE void openExec(const QString &exec);

     Q_INVOKABLE void addLauncher(bool isPopup = false);
-- 
